import * as React from "react";
import { Command as CommandPrimitive } from "cmdk";
import { CheckIcon, ChevronsUpDownIcon, XIcon } from "lucide-react";

import { cn } from "@/lib/utils";
import { menuItem, menuLabel, menuSeparator } from "./_menu-styles";
import { Popover, PopoverAnchor, PopoverContent, PopoverTrigger } from "./popover";

/**
 * figma: Combobox — an input that filters a list.
 *
 *   <Combobox multiple showClear autoHighlight>
 *     <ComboboxChips>                       multi-select chips, inside the input
 *       <ComboboxChip>React</ComboboxChip>
 *     </ComboboxChips>
 *     <ComboboxInput placeholder="Framework" />
 *     <ComboboxContent>
 *       <ComboboxGroup>
 *         <ComboboxLabel>Frontend</ComboboxLabel>
 *         <ComboboxItem value="react">React</ComboboxItem>
 *       </ComboboxGroup>
 *       <ComboboxSeparator />
 *     </ComboboxContent>
 *   </Combobox>
 *
 * `render` lets any element act as the trigger; move ComboboxInput inside
 * ComboboxContent for that popup form.
 */
type ComboboxContextValue = {
  open: boolean;
  setOpen: (open: boolean) => void;
  value: string[];
  select: (value: string) => void;
  remove: (value: string) => void;
  clear: () => void;
  multiple: boolean;
  showClear: boolean;
  autoHighlight: boolean;
  disabled: boolean;
  search: string;
  setSearch: (s: string) => void;
  hasTrigger: boolean;
};

const ComboboxContext = React.createContext<ComboboxContextValue | null>(null);

function useCombobox() {
  const ctx = React.useContext(ComboboxContext);
  if (!ctx) throw new Error("Combobox parts must be used within <Combobox>.");
  return ctx;
}

function Combobox({
  className,
  children,
  multiple = false,
  showClear = false,
  autoHighlight = false,
  disabled = false,
  open: openProp,
  onOpenChange,
  value: valueProp,
  defaultValue,
  onValueChange,
  render,
  ...props
}: Omit<React.ComponentProps<"div">, "defaultValue" | "onChange"> & {
  multiple?: boolean;
  showClear?: boolean;
  autoHighlight?: boolean;
  disabled?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  /** Render the combobox from a button or any other element. */
  render?: React.ReactNode;
}) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(false);
  const open = openProp ?? uncontrolledOpen;
  const setOpen = React.useCallback(
    (next: boolean) => (onOpenChange ? onOpenChange(next) : setUncontrolledOpen(next)),
    [onOpenChange]
  );

  const [uncontrolledValue, setUncontrolledValue] = React.useState<string[]>(defaultValue ?? []);
  const value = valueProp ?? uncontrolledValue;
  const commit = React.useCallback(
    (next: string[]) => (onValueChange ? onValueChange(next) : setUncontrolledValue(next)),
    [onValueChange]
  );

  const [search, setSearch] = React.useState("");

  const select = React.useCallback(
    (v: string) => {
      if (multiple) commit(value.includes(v) ? value.filter((x) => x !== v) : [...value, v]);
      else {
        commit([v]);
        setOpen(false);
      }
      setSearch("");
    },
    [multiple, value, commit, setOpen]
  );

  const remove = React.useCallback((v: string) => commit(value.filter((x) => x !== v)), [value, commit]);
  const clear = React.useCallback(() => commit([]), [commit]);

  const ctx: ComboboxContextValue = {
    open, setOpen, value, select, remove, clear,
    multiple, showClear, autoHighlight, disabled, search, setSearch,
    hasTrigger: render != null,
  };

  return (
    <ComboboxContext.Provider value={ctx}>
      <Popover open={open} onOpenChange={setOpen}>
        <div
          data-slot="combobox"
          data-disabled={disabled || undefined}
          className={cn("relative w-full", className)}
          {...props}
        >
          {render ? <PopoverTrigger asChild>{render}</PopoverTrigger> : <PopoverAnchor asChild><div>{null}</div></PopoverAnchor>}
          {children}
        </div>
      </Popover>
    </ComboboxContext.Provider>
  );
}

/**
 * The text input. Wraps itself in the InputGroup box so an InputGroupAddon can
 * sit beside it. Omit it here and place it inside ComboboxContent for the
 * popup form.
 */
function ComboboxInput({
  className,
  children,
  ...props
}: React.ComponentProps<"input">) {
  const { setOpen, search, setSearch, disabled, showClear, value, clear } = useCombobox();
  return (
    <div
      data-slot="combobox-input"
      className={cn(
        "group/combobox-input flex h-8 w-full items-center gap-2 rounded-lg border border-input bg-background px-2.5",
        "shadow-xs transition-[color,box-shadow]",
        "has-[input:focus-visible]:border-ring has-[input:focus-visible]:ring-ring-subtle has-[input:focus-visible]:ring-[3px]",
        "has-[input[aria-invalid=true]]:border-destructive has-[input[aria-invalid=true]]:ring-ring-destructive has-[input[aria-invalid=true]]:ring-[3px]",
        "data-[disabled]:pointer-events-none data-[disabled]:bg-input/50",
        className
      )}
      data-disabled={disabled || undefined}
    >
      {children}
      <input
        role="combobox"
        disabled={disabled}
        value={search}
        onChange={(e) => {
          setSearch(e.target.value);
          setOpen(true);
        }}
        onFocus={() => setOpen(true)}
        className="h-full min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
        {...props}
      />
      {showClear && value.length ? (
        <button
          type="button"
          aria-label="Clear"
          onClick={clear}
          className="shrink-0 text-muted-foreground hover:text-foreground"
        >
          <XIcon className="size-3.5" />
        </button>
      ) : null}
      <ChevronsUpDownIcon className="size-4 shrink-0 text-muted-foreground" />
    </div>
  );
}

/** The chips shown for a multi-select combobox. Render inside ComboboxInput. */
function ComboboxChips({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="combobox-chips"
      className={cn("flex shrink-0 items-center gap-1", className)}
      {...props}
    />
  );
}

function ComboboxChip({
  className,
  value,
  children,
  ...props
}: React.ComponentProps<"span"> & { value?: string }) {
  const { remove, disabled } = useCombobox();
  return (
    <span
      data-slot="combobox-chip"
      className={cn(
        "inline-flex h-5 items-center gap-1 rounded-sm bg-secondary px-1.5 text-xs font-medium",
        "data-[disabled]:opacity-50",
        className
      )}
      data-disabled={disabled || undefined}
      {...props}
    >
      {children}
      {value && !disabled ? (
        <button
          type="button"
          aria-label={`Remove ${value}`}
          onClick={() => remove(value)}
          className="text-muted-foreground hover:text-foreground"
        >
          <XIcon className="size-3" />
        </button>
      ) : null}
    </span>
  );
}

function ComboboxContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof PopoverContent>) {
  const { search, setSearch, autoHighlight } = useCombobox();
  return (
    <PopoverContent
      data-slot="combobox-content"
      align="start"
      sideOffset={4}
      onOpenAutoFocus={(e) => e.preventDefault()}
      className={cn("w-(--radix-popover-trigger-width) min-w-52 p-1", className)}
      {...props}
    >
      <CommandPrimitive
        shouldFilter
        value={autoHighlight ? undefined : ""}
        className="w-full"
      >
        <CommandPrimitive.Input value={search} onValueChange={setSearch} className="sr-only" />
        <ComboboxList>{children}</ComboboxList>
      </CommandPrimitive>
    </PopoverContent>
  );
}

function ComboboxList({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.List>) {
  return (
    <CommandPrimitive.List
      data-slot="combobox-list"
      className={cn("max-h-64 overflow-y-auto", className)}
      {...props}
    />
  );
}

function ComboboxEmpty({ ...props }: React.ComponentProps<typeof CommandPrimitive.Empty>) {
  return (
    <CommandPrimitive.Empty
      data-slot="combobox-empty"
      className="py-6 text-center text-sm text-muted-foreground"
      {...props}
    />
  );
}

function ComboboxGroup({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Group>) {
  return (
    <CommandPrimitive.Group
      data-slot="combobox-group"
      className={cn("text-foreground", className)}
      {...props}
    />
  );
}

function ComboboxLabel({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="combobox-label" className={cn(menuLabel, className)} {...props} />;
}

function ComboboxSeparator({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Separator>) {
  return (
    <CommandPrimitive.Separator
      data-slot="combobox-separator"
      className={cn(menuSeparator, className)}
      {...props}
    />
  );
}

function ComboboxItem({
  className,
  value,
  children,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Item> & { value: string }) {
  const { select, value: selected } = useCombobox();
  const isSelected = selected.includes(value);
  return (
    <CommandPrimitive.Item
      data-slot="combobox-item"
      value={value}
      onSelect={() => select(value)}
      className={cn(
        menuItem,
        "pe-8 data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground",
        className
      )}
      {...props}
    >
      {children}
      {isSelected ? <CheckIcon className="absolute end-2 size-4" /> : null}
    </CommandPrimitive.Item>
  );
}

export {
  Combobox,
  ComboboxInput,
  ComboboxChips,
  ComboboxChip,
  ComboboxContent,
  ComboboxList,
  ComboboxEmpty,
  ComboboxGroup,
  ComboboxLabel,
  ComboboxSeparator,
  ComboboxItem,
  useCombobox,
};
